import * as React from "react";

export type DiscountCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function DiscountCircleIcon({ size = 20, ...props }: DiscountCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx={12} cy={12} r={8} />
      <circle cx={12} cy={12} r={5} />
      <path d="M14.5 9.5 9.5 14.5" />
    </svg>
  );
}
